import{_ as t,o as a,c as r,au as o}from"./chunks/framework.BTTEhLNX.js";const p=JSON.parse('{"title":"krawler-teleray","description":"A Krawler based job to download data from the French gamma dose rate alert Teleray network.","frontmatter":{"title":"krawler-teleray","description":"A Krawler based job to download data from the French gamma dose rate alert Teleray network."},"headers":[],"relativePath":"packages/krawler-teleray/index.md","filePath":"packages/krawler-teleray/index.md"}'),l={name:"packages/krawler-teleray/index.md"};function d(n,e,s,i,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-teleray" tabindex="-1">krawler-teleray <a class="header-anchor" href="#krawler-teleray" aria-label="Permalink to &quot;krawler-teleray&quot;">​</a></h1><p><em>A Krawler based job to download data from the French gamma dose rate alert <a href="https://doc.teleray.asnr.fr/documentation/api/api-teleray.html" target="_blank" rel="noreferrer">Teleray</a> network.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-teleray</strong> job scrapes gamma dose rate measurements from the following url: <a href="https://api.teleray.asnr.fr/wfs/collections/measures/items" target="_blank" rel="noreferrer">https://api.teleray.asnr.fr/wfs/collections/measures/items</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li>the <code>teleray-measures</code> collection stores the measurement data</li><li>the <code>teleray-stations</code> collection stores the station positions</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The job is executed according a specific cron expression. By default, every 10 minutes.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/k-teleray</code></td></tr><tr><td><code>STATIONS_COLLECTION</code></td><td>The name of the MongoDB collection for stations positions. The default value is <code>teleray-stations</code></td></tr><tr><td><code>MEASURES_COLLECTION</code></td><td>The name of the MongoDB collection for measures data. The default value is <code>teleray-measures</code></td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',11)])])}const f=t(l,[["render",d]]);export{p as __pageData,f as default};
